/* AppNearMiss01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* AppNearMiss01Mapper.selectMyReportList */
SELECT

FROM TB_NEAR_MISS A
     LEFT OUTER JOIN TB_BAIM_VAL_D C
        ON (
            A.CMPNY_CD = C.CMPNY_CD
        AND C.BAIM_VAL_CD = 'COM002'
        AND A.PROCESS_CD = C.BAIM_VAL_D_CD
        AND C.USE_YN = 'Y'
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.REPORTER_ID = #{gvUserCd}
  AND A.USE_YN = 'Y'

    AND A.REPORT_STATUS_CD = #{reportStatusCd}

ORDER BY A.OCCUR_DTIME DESC, A.NEAR_MISS_ID DESC

/* AppNearMiss01Mapper.selectSiteIncidentList */
SELECT

FROM TB_NEAR_MISS A
     LEFT OUTER JOIN TB_BAIM_VAL_D C
        ON (
            A.CMPNY_CD = C.CMPNY_CD
        AND C.BAIM_VAL_CD = 'COM002'
        AND A.PROCESS_CD = C.BAIM_VAL_D_CD
        AND C.USE_YN = 'Y'
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

    AND A.REPORT_STATUS_CD = #{reportStatusCd}


    AND A.INCIDENT_TYPE_CD = #{incidentTypeCd}


    AND A.POTENTIAL_SEVERITY_CD = #{potentialSeverityCd}


    AND A.OCCUR_DTIME >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')


    AND A.OCCUR_DTIME <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')

ORDER BY A.REPORT_STATUS_CD, A.OCCUR_DTIME DESC, A.NEAR_MISS_ID DESC

/* AppNearMiss01Mapper.selectStatusCounts */
SELECT
    COALESCE(SUM(CASE WHEN A.REPORT_STATUS_CD = '100' THEN 1 ELSE 0 END), 0) AS receivedCnt
  , COALESCE(SUM(CASE WHEN A.REPORT_STATUS_CD = '200' THEN 1 ELSE 0 END), 0) AS reviewingCnt
  , COALESCE(SUM(CASE WHEN A.REPORT_STATUS_CD = '300' THEN 1 ELSE 0 END), 0) AS actingCnt
  , COALESCE(SUM(CASE WHEN A.REPORT_STATUS_CD = '400' THEN 1 ELSE 0 END), 0) AS completedCnt
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

    AND A.INCIDENT_TYPE_CD = #{incidentTypeCd}


    AND A.POTENTIAL_SEVERITY_CD = #{potentialSeverityCd}


    AND A.OCCUR_DTIME >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')


    AND A.OCCUR_DTIME <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')

/* AppNearMiss01Mapper.selectIncidentInfo */
SELECT

FROM TB_NEAR_MISS A
     LEFT OUTER JOIN TB_BAIM_VAL_D C
        ON (
            A.CMPNY_CD = C.CMPNY_CD
        AND C.BAIM_VAL_CD = 'COM002'
        AND A.PROCESS_CD = C.BAIM_VAL_D_CD
        AND C.USE_YN = 'Y'
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID = #{nearMissId}
  AND A.USE_YN = 'Y'

/* AppNearMiss01Mapper.selectReportMeta */
SELECT
    A.CMPNY_CD          AS cmpnyCd
  , A.SITE_CD           AS siteCd
  , A.NEAR_MISS_ID      AS nearMissId
  , A.REPORT_STATUS_CD  AS reportStatusCd
  , A.REPORTER_ID       AS reporterId
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID = #{nearMissId}
  AND A.USE_YN = 'Y'

/* AppNearMiss01Mapper.selectNextNearMissId */
SELECT
    CONCAT(
        'NM'
      , DATE_FORMAT(NOW(), '%Y%m%d')
      , LPAD(
            IFNULL(
                MAX(CAST(SUBSTR(A.NEAR_MISS_ID, 11, 3) AS UNSIGNED))
              , 0
            ) + 1
          , 3, '0'
        )
    )
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID LIKE CONCAT('NM', DATE_FORMAT(NOW(), '%Y%m%d'), '%')

