/* AppNearMiss01Mapper.insertReport */
INSERT INTO TB_NEAR_MISS
(
    CMPNY_CD
  , SITE_CD
  , NEAR_MISS_ID
  , INCIDENT_TYPE_CD
  , PROCESS_CD
  , OCCUR_DTIME
  , LOCATION_DESC
  , DESCRIPTION
  , POTENTIAL_SEVERITY_CD
  , IMMEDIATE_ACTION_DESC
  , FILE_MGMT_CD
  , REPORT_STATUS_CD
  , REPORTER_ID
  , REPORT_DTIME
  , USE_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{siteCd}
  , #{nearMissId}
  , #{incidentTypeCd}
  , #{processCd}
  , STR_TO_DATE(#{occurDtime}, '%Y-%m-%d %H:%i')
  , #{locationDesc}
  , #{description}
  , #{potentialSeverityCd}
  , #{immediateActionDesc}
  , #{fileMgmtCd}
  , '100'
  , #{gvUserCd}
  , NOW()
  , 'Y'
  , #{gvUserCd}
  , NOW()
)

mapper.update:
/* AppNearMiss01Mapper.updateFirstReview */
UPDATE TB_NEAR_MISS
SET
    REPORT_STATUS_CD       = '200'
  , ADMIN_TEMP_ACTION_DESC = #{adminTempActionDesc}
  , REVIEWER_ID            = #{gvUserCd}
  , REVIEW_DTIME           = NOW()
  , UPDATE_NO              = #{gvUserCd}
  , UPDATE_DATE            = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NEAR_MISS_ID = #{nearMissId}
  AND REPORT_STATUS_CD = '100'
  AND USE_YN = 'Y'

/* AppNearMiss01Mapper.updateReject */
UPDATE TB_NEAR_MISS
SET
    REPORT_STATUS_CD = '900'
  , REJECT_REASON    = #{rejectReason}

  , ADMIN_TEMP_ACTION_DESC = #{adminTempActionDesc}

  , REVIEWER_ID      = #{gvUserCd}
  , REVIEW_DTIME     = NOW()
  , UPDATE_NO        = #{gvUserCd}
  , UPDATE_DATE      = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NEAR_MISS_ID = #{nearMissId}
  AND REPORT_STATUS_CD = '100'
  AND USE_YN = 'Y'

