/* AppNearMiss01Mapper.selectSiteSafetyManagers */ SELECT U.USER_CD FROM TB_USER U INNER JOIN TB_USER_SITE_AUTH SA ON ( U.CMPNY_CD = SA.CMPNY_CD AND U.USER_CD = SA.USER_CD AND SA.SITE_CD = #{siteCd} AND SA.USE_YN = 'Y' ) WHERE U.CMPNY_CD = #{cmpnyCd} AND U.USE_YN = 'Y' AND U.ACCOUNT_STATUS = '01' AND U.AUTH_CD IN
#{authCd}
GROUP BY U.USER_CD

mapper.insert:
/* AppNearMiss01Mapper.insertNotiOutbox */
INSERT INTO TB_NOTI_OUTBOX
(
    NOTI_ID
  , CMPNY_CD
  , SITE_CD
  , TARGET_USER_CD
  , NOTI_TYPE
  , CHANNEL
  , TITLE
  , BODY
  , DATA_PAYLOAD
  , SEND_STATUS
  , RETRY_CNT
  , DEDUP_KEY
  , DEL_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    (SELECT CONCAT(
        'N'
      , DATE_FORMAT(NOW(), '%Y%m%d')
      , LPAD(
            IFNULL(
                MAX(CAST(SUBSTR(T.NOTI_ID, 10, 3) AS UNSIGNED))
              , 0
            ) + 1
          , 3, '0'
        )
    ) FROM TB_NOTI_OUTBOX T
      WHERE T.CMPNY_CD = #{cmpnyCd}
        AND T.NOTI_ID LIKE CONCAT('N', DATE_FORMAT(NOW(), '%Y%m%d'), '%'))
  , #{cmpnyCd}
  , #{siteCd}
  , #{targetUserCd}
  , #{notiType}
  , 'PUSH'
  , #{title}
  , #{body}
  , #{dataPayload}
  , 'PENDING'
  , 0
  , #{dedupKey}
  , 'N'
  , #{insertNo}
  , NOW()
)
